"""AUTO-GENERATED moderation route classification (Phase 2).

Капабилити-карта: каждый state-changing маршрут отнесён к бакету —
  A  = мутация данных дашборда, МОДЕРИРУЕМА (module+action; needs_handler —
       у модуля пока нет apply-хендлера, завести в Фазе 4);
  B  = self-service/личное, пишет напрямую;
  C  = система/админ, пишет напрямую;
  D  = upload/multipart (бинарь; JSON-commit половина импорта — уже в A);
  N  = не пишет БД (compute/parse/validate) — исключён.

ЭТО НЕ ПОЛИТИКА, А ТЕХНИЧЕСКАЯ КАРТА (что МОЖНО модерировать и чем применять).
Политика «что модерируется и для кого» — в DB-конфиге/панели (Фаза 3/5).

Файл СГЕНЕРИРОВАН и держится в актуальности CI-тестом
tests/test_moderation_route_coverage.py: новый write-роут не пройдёт тест,
пока не классифицирован здесь (deny-by-default на уровне процесса).
"""
from __future__ import annotations

from typing import NamedTuple, Optional


class RouteClass(NamedTuple):
    bucket: str                 # "A" | "B" | "C" | "D" | "N"
    module: Optional[str] = None    # canonical module (bucket A)
    action: Optional[str] = None    # write action (bucket A)
    needs_handler: bool = False     # A-модуль без apply-хендлера (Фаза 4)


