def route_class_for(endpoint_module: str, endpoint_name: str, method: str) -> Optional[RouteClass]:
    """Классификация маршрута по (module-пути эндпоинта, имени, методу). None —
    если не классифицирован (CI-тест такого не допустит)."""
    stem = endpoint_module.rsplit(".", 1)[-1]
    return ROUTE_CLASS.get(f"{stem}:{endpoint_name}:{method.upper()}")


MODERATABLE_MODULES: frozenset[str] = frozenset(
    rc.module for rc in ROUTE_CLASS.values() if rc.bucket == "A" and rc.module
)

# A-модули, у которых ПОКА нет apply-хендлера (одобрение уйдёт в skip) — Фаза 4.
MODULES_NEEDING_HANDLER: frozenset[str] = frozenset(
    rc.module for rc in ROUTE_CLASS.values()
    if rc.bucket == "A" and rc.needs_handler and rc.module
)
